mapper.select:
SELECT q.id AS doc_id, q.quote_no AS doc_no, q.quote_date AS biz_date, p.id AS partner_id, p.code AS partner_code,
       p.name AS partner_name, i.qty, i.price, i.amount, COALESCE(i.remark, q.remark) AS remark
FROM scm_quotation_item i
JOIN scm_quotation q ON q.id = i.quotation_id
JOIN scm_customer p ON p.id = q.customer_id
WHERE i.material_id = #{q.materialId}

AND q.quote_date >= #{q.start}
AND q.quote_date <= #{q.end}
ORDER BY q.quote_date DESC, q.id DESC, i.id DESC
LIMIT #{q.limit}

SELECT d.id AS doc_id, d.doc_no, d.biz_date, p.id AS partner_id, p.code AS partner_code, p.name AS partner_name,
       i.qty, COALESCE(i.gross_price, i.price) AS price, i.amount + i.discount_share AS amount, COALESCE(i.remark, d.remark) AS remark
FROM scm_trade_doc_item i
JOIN scm_trade_doc d ON d.id = i.doc_id

    JOIN scm_customer p ON p.id = d.partner_id
    JOIN scm_supplier p ON p.id = d.partner_id

WHERE d.kind = #{kind} AND i.material_id = #{q.materialId}

AND d.biz_date >= #{q.start}
AND d.biz_date <= #{q.end}
ORDER BY d.biz_date DESC, d.id DESC, i.id DESC
LIMIT #{q.limit}

SELECT p.id AS partner_id, p.code AS partner_code, p.name AS partner_name, COUNT(DISTINCT d.id) AS times,
       SUM(i.qty) AS qty, SUM(i.amount + i.discount_share) AS amount,
       CASE WHEN SUM(i.qty) = 0 THEN NULL ELSE ROUND(SUM(i.amount + i.discount_share) / SUM(i.qty), 4) END AS avg_price,
       MAX(d.biz_date) AS last_date
FROM scm_trade_doc_item i
JOIN scm_trade_doc d ON d.id = i.doc_id
JOIN scm_supplier p ON p.id = d.partner_id
WHERE d.kind = 'PURCHASE_IN' AND i.material_id = #{q.materialId}

AND d.biz_date >= #{q.start}
AND d.biz_date <= #{q.end}
GROUP BY p.id, p.code, p.name
ORDER BY SUM(i.qty) DESC
LIMIT #{q.limit}

mapper.sql:
SELECT d.id AS doc_id, d.doc_no, d.biz_date, p.id AS partner_id, p.code AS partner_code, p.name AS partner_name, i.qty, COALESCE(i.gross_price, i.price) AS price, cu.nickname AS create_by_name, pu.nickname AS post_by_name FROM scm_trade_doc_item i JOIN scm_trade_doc d ON d.id = i.doc_id
JOIN scm_customer p ON p.id = d.partner_id JOIN scm_supplier p ON p.id = d.partner_id
LEFT JOIN sys_user cu ON cu.id = d.create_by LEFT JOIN sys_user pu ON pu.id = d.post_by WHERE d.kind = #{kind} AND i.material_id = #{q.materialId} AND COALESCE(i.gross_price, i.price) > 0 AND p.id = #{q.partnerId}
AND (p.code LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%') OR p.phone LIKE CONCAT('%', #{q.keyword}, '%'))
AND d.biz_date >= #{q.start} AND d.biz_date <= #{q.end}
